/* nd_psolk.c: NPSO2D, the pso table lookup of the combine decision. nd_pso_find takes the walker's NdCombIn and fills the NdCombOut of the key
 * whose inputs equal it (nd_pso_in_eq): 1, or 0 when no key matches. The table (nd_pso_tab.c, generated by gen_pso_main.c) holds nd_pso_key (the
 * keys sorted by (cw0, cw1)), nd_pso_small (the small part of each key's comb, index = key si), nd_pso_plan (the distinct plans) and nd_pso_stage_raw (their stages) and nd_pso_nkey.
 * Binary search, no division. nd_pso() is not used here (its table is not linked). */
#include <stdint.h>
#include <string.h>
#include "ultra64.h"
#include "nd.h"
#include "nd_api.h"
#include "pm_gpu.h"

extern const NdPsoKey nd_pso_key[];                     /* nd_pso_tab.c */
extern const NdPsoSmall nd_pso_small[];                 /* nd_pso_tab.c */
extern const NdPlanRec nd_pso_plan[];                   /* nd_pso_tab.c */
extern const uint8_t nd_pso_stage_raw[][sizeof(PmTevStage)]; /* nd_pso_tab.c */
extern const unsigned nd_pso_nkey;                      /* nd_pso_tab.c */

int nd_pso_find_i(const NdCombIn* w, unsigned vprim, NdCombOut* o) { /* NDR0A: the key index m on a hit, -1 on none */
    unsigned lo = 0, hi = nd_pso_nkey, m;
    while (lo < hi) { /* the lower bound of (w0, w1) in the keys */
        m = (lo + hi) >> 1;
        const NdPsoKey* k = &nd_pso_key[m];
        if (k->cw0 < w->w0 || (k->cw0 == w->w0 && k->cw1 < w->w1)) lo = m + 1;
        else hi = m;
    }
    for (m = lo; m < nd_pso_nkey; m++) {
        const NdPsoKey* k = &nd_pso_key[m];
        if (k->cw0 != w->w0 || k->cw1 != w->w1) break;
        if (nd_pso_in_eq(k, w, vprim)) {
            const NdPsoSmall* s = &nd_pso_small[k->si];
            memset(o, 0, sizeof *o);
            o->leg = s->leg; o->mode5 = s->mode5; o->pat = s->pat; o->use = s->use; o->why = s->why; o->cyc = s->cyc; o->dual = s->dual;
            o->plan_on = s->plan_on; o->cc_on = s->cc_on; o->env_on = s->env_on; o->cc = s->cc;
            if (s->plan_on) {
                const NdPlanRec* r = &nd_pso_plan[s->pi];
                memset(&o->plan, 0, sizeof o->plan);
                o->plan.n = r->n; o->plan.buf = r->buf; o->plan.vtx = r->vtx;
                o->plan.bufname = r->bufname; o->plan.vtxname = r->vtxname;
                o->plan.uses_tex = r->uses_tex; o->plan.uses_sha = r->uses_sha; o->plan.uses_tex1 = r->uses_tex1; o->plan.uses_noise = r->uses_noise;
                memcpy(o->plan.ks, r->ks, sizeof o->plan.ks); memcpy(o->plan.fold, r->fold, sizeof o->plan.fold);
                for (unsigned i = 0; i < 6; i++) memcpy(&o->plan.st[i], nd_pso_stage_raw[r->si[i]], sizeof(PmTevStage));
            }
            return (int)m;
        }
    }
    return -1;
}
int nd_pso_find(const NdCombIn* w, unsigned vprim, NdCombOut* o) { return nd_pso_find_i(w, vprim, o) >= 0; }
